	for v, d := range degree {
		if d > 0 {
			start = v
			break
		}
	}
	if start < 0 {
		return true
	}
	seen := map[int]bool{start: true}
	stack := []int{start}
	for len(stack) > 0 {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, w := range adjacent[v] {
			if !seen[w] {
				seen[w] = true
				stack = append(stack, w)
			}
		}
	}
	for v, d := range degree {
		if d > 0 && !seen[v] {
			return false
		}
	}
	return true
}

